begin;

create table public."KHO" (
  "ma_kho" int generated by default as identity primary key,
  "ten_kho" varchar not null,
  "dia_chi" varchar not null,
  "trang_thai" int not null default 1
);

create table public."NHAN_VIEN" (
  "ma_nhan_vien" varchar primary key,
  "ma_kho" int,
  "loai_nhan_vien" varchar not null,
  "ho_ten" varchar not null,
  "cccd" varchar unique,
  "email" varchar,
  "sdt" varchar,
  "luong" decimal(18,2),
  "trang_thai" int not null default 1,
  check (loai_nhan_vien IN ('ADMIN', 'THU_KHO')),
  check ((loai_nhan_vien = 'ADMIN' AND ma_kho IS NULL) OR (loai_nhan_vien = 'THU_KHO' AND ma_kho IS NOT NULL))
);

create table public."TAI_KHOAN" (
  "ma_tk" varchar primary key,
  "ten_tai_khoan" varchar not null unique,
  "email" varchar unique,
  "mat_khau_hash" varchar not null,
  "ma_kh" varchar unique,
  "ma_nhan_vien" varchar unique,
  "trang_thai" int not null default 1,
  check ((ma_kh IS NOT NULL AND ma_nhan_vien IS NULL) OR (ma_kh IS NULL AND ma_nhan_vien IS NOT NULL))
);

create table public."KHACH_HANG" (
  "ma_kh" varchar primary key,
  "ten_kh" varchar not null,
  "sdt" varchar,
  "dia_chi_chi_tiet_md" varchar,
  "tinh_thanh_md" varchar,
  "xa_phuong_md" varchar
);

create table public."LOAI_SP" (
  "ma_loai_sp" varchar primary key,
  "ten_loai_sp" varchar not null unique,
  "trang_thai" int not null default 1
);

create table public."SAN_PHAM" (
  "ma_sp" varchar primary key,
  "sku" varchar not null unique,
  "ten_sp" varchar not null,
  "ma_loai_sp" varchar not null,
  "thuong_hieu" varchar,
  "gia_ban_hien_tai" decimal(18,2) not null,
  "mo_ta" text,
  "thong_so_ky_thuat" text,
  "don_vi" varchar not null default 'Cai',
  "bao_hanh_thang" int not null default 0,
  "duong_dan_anh" varchar,
  "trang_thai" int not null default 1,
  check (gia_ban_hien_tai >= 0),
  check (bao_hanh_thang >= 0)
);

create table public."TON_KHO" (
  "ma_kho" int not null,
  "sku" varchar not null,
  "so_luong_ton" int not null default 0 check (so_luong_ton >= 0),
  "cap_nhat_luc" timestamptz,
  primary key ("ma_kho", "sku")
);

create table public."NHA_CUNG_CAP" (
  "ma_ncc" int generated by default as identity primary key,
