  "trang_thai" varchar not null default 'NHAP',
  "nguoi_tao" varchar not null,
  "nguoi_cap_nhat" varchar,
  "nguoi_xac_nhan" varchar,
  "ghi_chu" text
);

create table public."CT_PHIEU_NHAP" (
  "ma_phieu_nhap" int not null,
  "sku" varchar not null,
  "so_luong_nhap" int not null check (so_luong_nhap > 0),
  "gia_nhap" decimal(18,2) not null check (gia_nhap >= 0),
  primary key ("ma_phieu_nhap", "sku")
);

create table public."PHIEU_CHUYEN_KHO" (
  "ma_phieu_chuyen" int generated by default as identity primary key,
  "ma_kho_xuat" int not null,
  "ma_kho_nhan" int not null,
  "ngay_tao" timestamptz not null,
  "ngay_xuat" timestamptz,
  "ngay_nhan" timestamptz,
  "trang_thai" varchar not null default 'NHAP',
  "nguoi_tao" varchar not null,
  "nguoi_xuat" varchar,
  "nguoi_nhan" varchar,
  "ghi_chu" text,
  check (ma_kho_xuat <> ma_kho_nhan)
);

create table public."CT_CHUYEN_KHO" (
  "ma_phieu_chuyen" int not null,
  "sku" varchar not null,
  "so_luong" int not null check (so_luong > 0),
  primary key ("ma_phieu_chuyen", "sku")
);

create table public."DON_HANG" (
