);

create table public."CT_DON_HANG" (
  "ma_ct_donhang" int generated by default as identity primary key,
  "ma_donhang" varchar not null,
  "sku" varchar not null,
  "ma_kho_xuat" int not null,
  "ten_sp_luc_ban" varchar not null,
  "don_vi_luc_ban" varchar not null,
  "so_luong" int not null check (so_luong > 0),
  "don_gia" decimal(18,2) not null,
  "giam_gia" decimal(18,2) not null default 0,
  "giam_gia_voucher" decimal(18,2) not null default 0,
  "thue_suat" decimal(5,2) not null,
  "tien_thue" decimal(18,2) not null,
  "thanh_tien" decimal(18,2) not null,
  check (don_gia >= 0 AND giam_gia >= 0 AND giam_gia_voucher >= 0 AND giam_gia + giam_gia_voucher <= so_luong * don_gia),
  check (thue_suat >= 0 AND thue_suat <= 100 AND tien_thue >= 0),
  check (thanh_tien = so_luong * don_gia - giam_gia - giam_gia_voucher + tien_thue)
);

create table public."HOA_DON" (
  "ma_hoadon" varchar primary key,
  "ma_donhang" varchar not null unique,
  "thoi_gian_lap" timestamptz not null,
  "ten_nguoi_mua" varchar,
