  "dia_chi_nguoi_mua" varchar,
  "tong_tien_giam" decimal(18,2) not null default 0,
  "tong_tien_truoc_thue" decimal(18,2) not null,
  "tong_tien_thue" decimal(18,2) not null,
  "tong_tien_sau_thue" decimal(18,2) not null,
  "nguoi_lap" varchar not null,
  check (tong_tien_giam >= 0),
  check (tong_tien_truoc_thue >= 0 AND tong_tien_thue >= 0 AND tong_tien_sau_thue >= 0),
  check (tong_tien_sau_thue = tong_tien_truoc_thue + tong_tien_thue)
);

create table public."THANH_TOAN" (
