);

create table public."CHUONG_TRINH_KHUYEN_MAI" (
  "ma_ctkm" int generated by default as identity primary key,
  "ten_chuong_trinh" varchar not null,
  "mo_ta" text,
  "ngay_bat_dau" timestamptz not null,
  "ngay_ket_thuc" timestamptz not null,
  "trang_thai" varchar not null default 'NHAP',
  "nguoi_tao" varchar not null,
  "ngay_tao" timestamptz not null,
  check (ngay_ket_thuc > ngay_bat_dau),
  check (trang_thai IN ('NHAP', 'HOAT_DONG', 'TAM_DUNG', 'KET_THUC'))
);

create table public."VOUCHER" (
  "ma_voucher" int generated by default as identity primary key,
  "ma_ctkm" int not null,
  "ma_code" varchar not null unique,
  "loai_giam" varchar not null,
  "gia_tri_giam" decimal(18,2) not null,
  "giam_toi_da" decimal(18,2),
  "gia_tri_don_toi_thieu" decimal(18,2) not null default 0,
  "gioi_han_tong_luot" int,
  "gioi_han_moi_khach" int not null default 1,
  "trang_thai" varchar not null default 'HOAT_DONG',
  "ngay_tao" timestamptz not null,
  check (loai_giam IN ('PHAN_TRAM', 'SO_TIEN')),
  check (gia_tri_giam > 0 AND (loai_giam <> 'PHAN_TRAM' OR gia_tri_giam <= 100)),
  check (giam_toi_da IS NULL OR (loai_giam = 'PHAN_TRAM' AND giam_toi_da > 0)),
  check (gia_tri_don_toi_thieu >= 0),
  check (gioi_han_tong_luot IS NULL OR gioi_han_tong_luot > 0),
  check (gioi_han_moi_khach > 0),
  check (trang_thai IN ('HOAT_DONG', 'TAM_DUNG'))
);

create table public."SU_DUNG_VOUCHER" (
